-- 00316: Read-only workspaces for the remaining warehouse lists.
-- Adds five STABLE, SECURITY INVOKER functions. No business rows are changed.

create or replace function public.get_internal_export_list_workspace(
  p_page integer default 0, p_page_size integer default 20,
  p_search text default null, p_search_field text default 'all',
  p_statuses text[] default null,
  p_date_from timestamptz default null, p_date_to_exclusive timestamptz default null,
  p_created_by uuid default null, p_amount_min numeric default null, p_amount_max numeric default null,
  p_branch_id uuid default null
) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare v_actor uuid:=auth.uid(); v_tenant uuid; v_all boolean; v_q text:=nullif(trim(coalesce(p_search,'')),''); v_page integer:=greatest(coalesce(p_page,0),0); v_size integer:=least(greatest(coalesce(p_page_size,20),1),200); v_result jsonb;
begin
  if v_actor is null then raise exception using errcode='42501',message='INTERNAL_EXPORT_LIST_AUTH_REQUIRED'; end if;
  v_tenant:=public.get_user_tenant_id();
  if v_tenant is null or not exists(select 1 from public.profiles p where p.id=v_actor and p.tenant_id=v_tenant and coalesce(p.is_active,true)) then raise exception using errcode='42501',message='INTERNAL_EXPORT_LIST_PROFILE_DENIED'; end if;
  if not public.user_has_permission(v_actor,'inventory.view') then raise exception using errcode='42501',message='INTERNAL_EXPORT_LIST_PERMISSION_DENIED'; end if;
  v_all:=public.user_has_permission(v_actor,'reports.view_all_branches') or public.user_has_permission(v_actor,'system.manage_branches');
  if p_branch_id is not null and (not exists(select 1 from public.branches b where b.id=p_branch_id and b.tenant_id=v_tenant) or (not v_all and not public.user_has_branch_access(v_actor,p_branch_id))) then raise exception using errcode='42501',message='INTERNAL_EXPORT_LIST_BRANCH_DENIED'; end if;
  if p_amount_min is not null and p_amount_max is not null and p_amount_min>p_amount_max then raise exception using errcode='22023',message='INTERNAL_EXPORT_LIST_AMOUNT_RANGE_INVALID'; end if;
  with scoped as (
    select e.*,p.full_name created_by_name,b.name branch_name,
      coalesce((select count(*) from public.internal_export_items i where i.export_id=e.id),0)::integer total_products
    from public.internal_exports e left join public.profiles p on p.id=e.created_by and p.tenant_id=v_tenant left join public.branches b on b.id=e.branch_id and b.tenant_id=v_tenant
    where e.tenant_id=v_tenant and ((p_branch_id is not null and e.branch_id=p_branch_id) or (p_branch_id is null and v_all) or (p_branch_id is null and not v_all and e.branch_id in(select x.branch_id from public.get_user_accessible_branches(v_actor)x)))
  ), filtered as (
    select s.* from scoped s where (v_q is null or case coalesce(p_search_field,'all')
      when 'code' then position(lower(v_q) in lower(coalesce(s.code,'')))>0
      when 'department' then position(lower(v_q) in lower(coalesce(s.department,'')))>0
      when 'note' then position(lower(v_q) in lower(coalesce(s.note,'')))>0
      when 'creator' then position(lower(v_q) in lower(coalesce(s.created_by_name,'')))>0
      when 'product' then exists(select 1 from public.internal_export_items i left join public.products pr on pr.id=i.product_id and pr.tenant_id=v_tenant where i.export_id=s.id and (position(lower(v_q) in lower(coalesce(i.product_name,'')))>0 or position(lower(v_q) in lower(coalesce(pr.code,'')))>0))
      else position(lower(v_q) in lower(coalesce(s.code,'')))>0 or position(lower(v_q) in lower(coalesce(s.department,'')))>0 or position(lower(v_q) in lower(coalesce(s.note,'')))>0 or position(lower(v_q) in lower(coalesce(s.created_by_name,'')))>0 or exists(select 1 from public.internal_export_items i left join public.products pr on pr.id=i.product_id and pr.tenant_id=v_tenant where i.export_id=s.id and (position(lower(v_q) in lower(coalesce(i.product_name,'')))>0 or position(lower(v_q) in lower(coalesce(pr.code,'')))>0)) end)
      and (coalesce(array_length(p_statuses,1),0)=0 or s.status=any(p_statuses)) and (p_date_from is null or s.created_at>=p_date_from) and (p_date_to_exclusive is null or s.created_at<p_date_to_exclusive) and (p_created_by is null or s.created_by=p_created_by) and (p_amount_min is null or s.total_amount>=p_amount_min) and (p_amount_max is null or s.total_amount<=p_amount_max)
  ), ranked as(select f.*,row_number() over(order by f.created_at desc,f.id) rn from filtered f), page_rows as(select * from ranked where rn>v_page*v_size and rn<=(v_page+1)*v_size order by rn), summary as(select count(*)::bigint total_count,count(*)filter(where status='completed')::bigint completed_count,count(*)filter(where status='draft')::bigint draft_count,count(*)filter(where status='cancelled')::bigint cancelled_count,coalesce(sum(total_amount)filter(where status='completed'),0)::numeric completed_value from filtered)
  select jsonb_build_object('items',coalesce((select jsonb_agg((to_jsonb(r)-'rn'-'created_by_name'-'branch_name')||jsonb_build_object('profiles',case when r.created_by_name is null then null else jsonb_build_object('full_name',r.created_by_name) end,'branches',case when r.branch_name is null then null else jsonb_build_object('name',r.branch_name) end) order by r.rn)from page_rows r),'[]'::jsonb),'total',(select total_count from summary),'summary',(select jsonb_build_object('completedCount',completed_count,'draftCount',draft_count,'cancelledCount',cancelled_count,'completedValue',completed_value)from summary)) into v_result;
  return v_result;
end $$;

create or replace function public.get_inventory_check_list_workspace(
  p_page integer default 0,p_page_size integer default 20,p_search text default null,p_search_field text default 'all',p_statuses text[] default null,p_date_from timestamptz default null,p_date_to_exclusive timestamptz default null,p_created_by uuid default null,p_branch_id uuid default null
) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare v_actor uuid:=auth.uid();v_tenant uuid;v_all boolean;v_q text:=nullif(trim(coalesce(p_search,'')),'');v_page integer:=greatest(coalesce(p_page,0),0);v_size integer:=least(greatest(coalesce(p_page_size,20),1),200);v_result jsonb;
begin
  if v_actor is null then raise exception using errcode='42501',message='INVENTORY_CHECK_LIST_AUTH_REQUIRED';end if;v_tenant:=public.get_user_tenant_id();
  if v_tenant is null or not exists(select 1 from public.profiles p where p.id=v_actor and p.tenant_id=v_tenant and coalesce(p.is_active,true)) then raise exception using errcode='42501',message='INVENTORY_CHECK_LIST_PROFILE_DENIED';end if;
  if not public.user_has_permission(v_actor,'inventory.view') then raise exception using errcode='42501',message='INVENTORY_CHECK_LIST_PERMISSION_DENIED';end if;
  v_all:=public.user_has_permission(v_actor,'reports.view_all_branches') or public.user_has_permission(v_actor,'system.manage_branches');
  if p_branch_id is not null and (not exists(select 1 from public.branches b where b.id=p_branch_id and b.tenant_id=v_tenant) or (not v_all and not public.user_has_branch_access(v_actor,p_branch_id))) then raise exception using errcode='42501',message='INVENTORY_CHECK_LIST_BRANCH_DENIED';end if;
  with scoped as(
    select c.*,p.full_name created_by_name,b.name branch_name,coalesce(a.total_products,0)::integer total_products,coalesce(a.increase_qty,0)::numeric increase_qty,coalesce(a.decrease_qty,0)::numeric decrease_qty,coalesce(a.increase_amount,0)::numeric increase_amount,coalesce(a.decrease_amount,0)::numeric decrease_amount
    from public.inventory_checks c left join public.profiles p on p.id=c.created_by and p.tenant_id=v_tenant left join public.branches b on b.id=c.branch_id and b.tenant_id=v_tenant
    left join lateral(select count(*) total_products,coalesce(sum(greatest(i.difference,0)),0) increase_qty,coalesce(sum(abs(least(i.difference,0))),0) decrease_qty,coalesce(sum(greatest(i.difference,0)*coalesce(i.unit_cost,pr.cost_price,0)),0) increase_amount,coalesce(sum(abs(least(i.difference,0))*coalesce(i.unit_cost,pr.cost_price,0)),0) decrease_amount from public.inventory_check_items i left join public.products pr on pr.id=i.product_id and pr.tenant_id=v_tenant where i.check_id=c.id)a on true
    where c.tenant_id=v_tenant and ((p_branch_id is not null and c.branch_id=p_branch_id)or(p_branch_id is null and v_all)or(p_branch_id is null and not v_all and c.branch_id in(select x.branch_id from public.get_user_accessible_branches(v_actor)x)))
  ),filtered as(select s.* from scoped s where(v_q is null or case coalesce(p_search_field,'all') when 'code' then position(lower(v_q)in lower(coalesce(s.code,'')))>0 when 'note' then position(lower(v_q)in lower(coalesce(s.note,'')))>0 when 'creator' then position(lower(v_q)in lower(coalesce(s.created_by_name,'')))>0 when 'product' then exists(select 1 from public.inventory_check_items i left join public.products pr on pr.id=i.product_id and pr.tenant_id=v_tenant where i.check_id=s.id and(position(lower(v_q)in lower(coalesce(i.product_name,'')))>0 or position(lower(v_q)in lower(coalesce(pr.code,'')))>0)) else position(lower(v_q)in lower(coalesce(s.code,'')))>0 or position(lower(v_q)in lower(coalesce(s.note,'')))>0 or position(lower(v_q)in lower(coalesce(s.created_by_name,'')))>0 or exists(select 1 from public.inventory_check_items i left join public.products pr on pr.id=i.product_id and pr.tenant_id=v_tenant where i.check_id=s.id and(position(lower(v_q)in lower(coalesce(i.product_name,'')))>0 or position(lower(v_q)in lower(coalesce(pr.code,'')))>0)) end)and(coalesce(array_length(p_statuses,1),0)=0 or s.status=any(p_statuses))and(p_date_from is null or s.created_at>=p_date_from)and(p_date_to_exclusive is null or s.created_at<p_date_to_exclusive)and(p_created_by is null or s.created_by=p_created_by)),ranked as(select f.*,row_number()over(order by f.created_at desc,f.id)rn from filtered f),page_rows as(select * from ranked where rn>v_page*v_size and rn<=(v_page+1)*v_size order by rn),summary as(select count(*)::bigint total_count,count(*)filter(where status in('draft','in_progress'))::bigint processing_count,count(*)filter(where status='balanced')::bigint balanced_count,count(*)filter(where status='cancelled')::bigint cancelled_count,coalesce(sum(increase_amount-decrease_amount),0)::numeric net_variance from filtered)
  select jsonb_build_object('items',coalesce((select jsonb_agg((to_jsonb(r)-'rn'-'created_by_name'-'branch_name')||jsonb_build_object('profiles',case when r.created_by_name is null then null else jsonb_build_object('full_name',r.created_by_name)end,'branches',case when r.branch_name is null then null else jsonb_build_object('name',r.branch_name)end)order by r.rn)from page_rows r),'[]'::jsonb),'total',(select total_count from summary),'summary',(select jsonb_build_object('processingCount',processing_count,'balancedCount',balanced_count,'cancelledCount',cancelled_count,'netVariance',net_variance)from summary))into v_result;return v_result;
end $$;

create or replace function public.get_stock_transfer_list_workspace(
  p_page integer default 0,p_page_size integer default 20,p_search text default null,p_search_field text default 'all',p_statuses text[] default null,p_date_from timestamptz default null,p_date_to_exclusive timestamptz default null,p_from_branch_id uuid default null,p_to_branch_id uuid default null,p_created_by uuid default null,p_item_count_min integer default null,p_item_count_max integer default null,p_branch_id uuid default null
) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare v_actor uuid:=auth.uid();v_tenant uuid;v_all boolean;v_q text:=nullif(trim(coalesce(p_search,'')),'');v_page integer:=greatest(coalesce(p_page,0),0);v_size integer:=least(greatest(coalesce(p_page_size,20),1),200);v_result jsonb;
begin
  if v_actor is null then raise exception using errcode='42501',message='STOCK_TRANSFER_LIST_AUTH_REQUIRED';end if;v_tenant:=public.get_user_tenant_id();if v_tenant is null or not exists(select 1 from public.profiles p where p.id=v_actor and p.tenant_id=v_tenant and coalesce(p.is_active,true))then raise exception using errcode='42501',message='STOCK_TRANSFER_LIST_PROFILE_DENIED';end if;if not public.user_has_permission(v_actor,'inventory.view')then raise exception using errcode='42501',message='STOCK_TRANSFER_LIST_PERMISSION_DENIED';end if;v_all:=public.user_has_permission(v_actor,'reports.view_all_branches')or public.user_has_permission(v_actor,'system.manage_branches');
  if p_branch_id is not null and(not exists(select 1 from public.branches b where b.id=p_branch_id and b.tenant_id=v_tenant)or(not v_all and not public.user_has_branch_access(v_actor,p_branch_id)))then raise exception using errcode='42501',message='STOCK_TRANSFER_LIST_BRANCH_DENIED';end if;if p_item_count_min is not null and p_item_count_max is not null and p_item_count_min>p_item_count_max then raise exception using errcode='22023',message='STOCK_TRANSFER_LIST_ITEM_RANGE_INVALID';end if;
  with scoped as(select t.*,fb.code from_branch_code,fb.name from_branch_name,tb.code to_branch_code,tb.name to_branch_name,p.full_name created_by_name from public.stock_transfers t join public.branches fb on fb.id=t.from_branch_id and fb.tenant_id=v_tenant join public.branches tb on tb.id=t.to_branch_id and tb.tenant_id=v_tenant left join public.profiles p on p.id=t.created_by and p.tenant_id=v_tenant where t.tenant_id=v_tenant and((p_branch_id is not null and(t.from_branch_id=p_branch_id or t.to_branch_id=p_branch_id))or(p_branch_id is null and v_all)or(p_branch_id is null and not v_all and(t.from_branch_id in(select x.branch_id from public.get_user_accessible_branches(v_actor)x)or t.to_branch_id in(select x.branch_id from public.get_user_accessible_branches(v_actor)x))))),filtered as(select s.* from scoped s where(v_q is null or case coalesce(p_search_field,'all')when 'code'then position(lower(v_q)in lower(s.code))>0 when 'from_branch_code'then position(lower(v_q)in lower(s.from_branch_code))>0 when 'from_branch_name'then position(lower(v_q)in lower(s.from_branch_name))>0 when 'to_branch_code'then position(lower(v_q)in lower(s.to_branch_code))>0 when 'to_branch_name'then position(lower(v_q)in lower(s.to_branch_name))>0 when 'creator_name'then position(lower(v_q)in lower(coalesce(s.created_by_name,'')))>0 when 'note'then position(lower(v_q)in lower(coalesce(s.note,'')))>0 when 'product_code'then exists(select 1 from public.stock_transfer_items i where i.transfer_id=s.id and position(lower(v_q)in lower(coalesce(i.product_code,'')))>0) when 'product_name'then exists(select 1 from public.stock_transfer_items i where i.transfer_id=s.id and position(lower(v_q)in lower(coalesce(i.product_name,'')))>0) else position(lower(v_q)in lower(s.code))>0 or position(lower(v_q)in lower(s.from_branch_name))>0 or position(lower(v_q)in lower(s.to_branch_name))>0 or position(lower(v_q)in lower(coalesce(s.created_by_name,'')))>0 or exists(select 1 from public.stock_transfer_items i where i.transfer_id=s.id and(position(lower(v_q)in lower(coalesce(i.product_code,'')))>0 or position(lower(v_q)in lower(coalesce(i.product_name,'')))>0))end)and(coalesce(array_length(p_statuses,1),0)=0 or s.status=any(p_statuses))and(p_date_from is null or s.created_at>=p_date_from)and(p_date_to_exclusive is null or s.created_at<p_date_to_exclusive)and(p_from_branch_id is null or s.from_branch_id=p_from_branch_id)and(p_to_branch_id is null or s.to_branch_id=p_to_branch_id)and(p_created_by is null or s.created_by=p_created_by)and(p_item_count_min is null or s.total_items>=p_item_count_min)and(p_item_count_max is null or s.total_items<=p_item_count_max)),ranked as(select f.*,row_number()over(order by f.created_at desc,f.id)rn from filtered f),page_rows as(select * from ranked where rn>v_page*v_size and rn<=(v_page+1)*v_size order by rn),summary as(select count(*)::bigint total_count,count(*)filter(where status='in_transit')::bigint in_transit_count,count(*)filter(where status='completed')::bigint completed_count,count(*)filter(where status='cancelled')::bigint cancelled_count,coalesce(sum(total_items),0)::bigint total_items_count from filtered)
  select jsonb_build_object('items',coalesce((select jsonb_agg((to_jsonb(r)-'rn'-'from_branch_code'-'from_branch_name'-'to_branch_code'-'to_branch_name'-'created_by_name')||jsonb_build_object('from_branch',jsonb_build_object('code',r.from_branch_code,'name',r.from_branch_name),'to_branch',jsonb_build_object('code',r.to_branch_code,'name',r.to_branch_name),'creator',case when r.created_by_name is null then null else jsonb_build_object('full_name',r.created_by_name)end)order by r.rn)from page_rows r),'[]'::jsonb),'total',(select total_count from summary),'summary',(select jsonb_build_object('inTransitCount',in_transit_count,'completedCount',completed_count,'cancelledCount',cancelled_count,'totalItems',total_items_count)from summary))into v_result;return v_result;
end $$;

create or replace function public.get_production_order_list_workspace(
  p_page integer default 0,p_page_size integer default 20,p_search text default null,p_search_field text default 'all',p_statuses text[] default null,p_date_from timestamptz default null,p_date_to_exclusive timestamptz default null,p_created_by uuid default null,p_qty_min numeric default null,p_qty_max numeric default null,p_branch_id uuid default null
) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare v_actor uuid:=auth.uid();v_tenant uuid;v_all boolean;v_q text:=nullif(trim(coalesce(p_search,'')),'');v_page integer:=greatest(coalesce(p_page,0),0);v_size integer:=least(greatest(coalesce(p_page_size,20),1),200);v_result jsonb;
begin
  if v_actor is null then raise exception using errcode='42501',message='PRODUCTION_LIST_AUTH_REQUIRED';end if;v_tenant:=public.get_user_tenant_id();if v_tenant is null or not exists(select 1 from public.profiles p where p.id=v_actor and p.tenant_id=v_tenant and coalesce(p.is_active,true))then raise exception using errcode='42501',message='PRODUCTION_LIST_PROFILE_DENIED';end if;if not public.user_has_permission(v_actor,'production.view')then raise exception using errcode='42501',message='PRODUCTION_LIST_PERMISSION_DENIED';end if;v_all:=public.user_has_permission(v_actor,'reports.view_all_branches')or public.user_has_permission(v_actor,'system.manage_branches');if p_branch_id is not null and(not exists(select 1 from public.branches b where b.id=p_branch_id and b.tenant_id=v_tenant)or(not v_all and not public.user_has_branch_access(v_actor,p_branch_id)))then raise exception using errcode='42501',message='PRODUCTION_LIST_BRANCH_DENIED';end if;if p_qty_min is not null and p_qty_max is not null and p_qty_min>p_qty_max then raise exception using errcode='22023',message='PRODUCTION_LIST_QTY_RANGE_INVALID';end if;
  with scoped as(select o.*,pr.name product_name,pr.code product_code,b.name branch_name,p.full_name created_by_name from public.production_orders o join public.products pr on pr.id=o.product_id and pr.tenant_id=v_tenant join public.branches b on b.id=o.branch_id and b.tenant_id=v_tenant left join public.profiles p on p.id=o.created_by and p.tenant_id=v_tenant where o.tenant_id=v_tenant and((p_branch_id is not null and o.branch_id=p_branch_id)or(p_branch_id is null and v_all)or(p_branch_id is null and not v_all and o.branch_id in(select x.branch_id from public.get_user_accessible_branches(v_actor)x)))),filtered as(select s.* from scoped s where(v_q is null or case coalesce(p_search_field,'all')when 'code'then position(lower(v_q)in lower(s.code))>0 when 'product_code'then position(lower(v_q)in lower(s.product_code))>0 when 'product_name'then position(lower(v_q)in lower(s.product_name))>0 when 'lot_number'then position(lower(v_q)in lower(coalesce(s.lot_number,'')))>0 when 'creator'then position(lower(v_q)in lower(coalesce(s.created_by_name,'')))>0 when 'note'then position(lower(v_q)in lower(coalesce(s.notes,'')))>0 else position(lower(v_q)in lower(s.code))>0 or position(lower(v_q)in lower(s.product_code))>0 or position(lower(v_q)in lower(s.product_name))>0 or position(lower(v_q)in lower(coalesce(s.lot_number,'')))>0 or position(lower(v_q)in lower(coalesce(s.created_by_name,'')))>0 or position(lower(v_q)in lower(coalesce(s.notes,'')))>0 end)and(coalesce(array_length(p_statuses,1),0)=0 or s.status=any(p_statuses))and(p_date_from is null or s.created_at>=p_date_from)and(p_date_to_exclusive is null or s.created_at<p_date_to_exclusive)and(p_created_by is null or s.created_by=p_created_by)and(p_qty_min is null or s.planned_qty>=p_qty_min)and(p_qty_max is null or s.planned_qty<=p_qty_max)),ranked as(select f.*,row_number()over(order by f.created_at desc,f.id)rn from filtered f),page_rows as(select * from ranked where rn>v_page*v_size and rn<=(v_page+1)*v_size order by rn),summary as(select count(*)::bigint total_count,count(*)filter(where status in('in_production','quality_check'))::bigint in_progress_count,count(*)filter(where status='completed' and actual_end>=(current_date::timestamp at time zone 'Asia/Ho_Chi_Minh') and actual_end<((current_date+1)::timestamp at time zone 'Asia/Ho_Chi_Minh'))::bigint completed_today_count,count(*)filter(where status='cancelled')::bigint cancelled_count,coalesce(sum(cogs_amount),0)::numeric total_cogs from filtered)
  select jsonb_build_object('items',coalesce((select jsonb_agg((to_jsonb(r)-'rn'-'product_name'-'product_code'-'branch_name'-'created_by_name')||jsonb_build_object('products',jsonb_build_object('name',r.product_name,'code',r.product_code),'branches',jsonb_build_object('name',r.branch_name),'profiles',case when r.created_by_name is null then null else jsonb_build_object('full_name',r.created_by_name)end)order by r.rn)from page_rows r),'[]'::jsonb),'total',(select total_count from summary),'summary',(select jsonb_build_object('inProgressCount',in_progress_count,'completedTodayCount',completed_today_count,'cancelledCount',cancelled_count,'totalCogs',total_cogs)from summary))into v_result;return v_result;
end $$;

create or replace function public.get_internal_sale_list_workspace(
  p_page integer default 0,p_page_size integer default 20,p_search text default null,p_search_field text default 'all',p_statuses text[] default null,p_date_from timestamptz default null,p_date_to_exclusive timestamptz default null,p_from_branch_id uuid default null,p_to_branch_id uuid default null,p_created_by uuid default null,p_amount_min numeric default null,p_amount_max numeric default null,p_branch_id uuid default null
) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare v_actor uuid:=auth.uid();v_tenant uuid;v_all boolean;v_q text:=nullif(trim(coalesce(p_search,'')),'');v_page integer:=greatest(coalesce(p_page,0),0);v_size integer:=least(greatest(coalesce(p_page_size,20),1),200);v_result jsonb;
begin
  if v_actor is null then raise exception using errcode='42501',message='INTERNAL_SALE_LIST_AUTH_REQUIRED';end if;v_tenant:=public.get_user_tenant_id();if v_tenant is null or not exists(select 1 from public.profiles p where p.id=v_actor and p.tenant_id=v_tenant and coalesce(p.is_active,true))then raise exception using errcode='42501',message='INTERNAL_SALE_LIST_PROFILE_DENIED';end if;if not public.user_has_permission(v_actor,'inventory.view')then raise exception using errcode='42501',message='INTERNAL_SALE_LIST_PERMISSION_DENIED';end if;v_all:=public.user_has_permission(v_actor,'reports.view_all_branches')or public.user_has_permission(v_actor,'system.manage_branches');if p_branch_id is not null and(not exists(select 1 from public.branches b where b.id=p_branch_id and b.tenant_id=v_tenant)or(not v_all and not public.user_has_branch_access(v_actor,p_branch_id)))then raise exception using errcode='42501',message='INTERNAL_SALE_LIST_BRANCH_DENIED';end if;if p_amount_min is not null and p_amount_max is not null and p_amount_min>p_amount_max then raise exception using errcode='22023',message='INTERNAL_SALE_LIST_AMOUNT_RANGE_INVALID';end if;
  with scoped as(select s.*,fb.code from_branch_code,fb.name from_branch_name,tb.code to_branch_code,tb.name to_branch_name,p.full_name created_by_name from public.internal_sales s join public.branches fb on fb.id=s.from_branch_id and fb.tenant_id=v_tenant join public.branches tb on tb.id=s.to_branch_id and tb.tenant_id=v_tenant left join public.profiles p on p.id=s.created_by and p.tenant_id=v_tenant where s.tenant_id=v_tenant and((p_branch_id is not null and(s.from_branch_id=p_branch_id or s.to_branch_id=p_branch_id))or(p_branch_id is null and v_all)or(p_branch_id is null and not v_all and(s.from_branch_id in(select x.branch_id from public.get_user_accessible_branches(v_actor)x)or s.to_branch_id in(select x.branch_id from public.get_user_accessible_branches(v_actor)x))))),filtered as(select s.* from scoped s where(v_q is null or case coalesce(p_search_field,'all')when 'code'then position(lower(v_q)in lower(s.code))>0 when 'from_branch_code'then position(lower(v_q)in lower(s.from_branch_code))>0 when 'from_branch_name'then position(lower(v_q)in lower(s.from_branch_name))>0 when 'to_branch_code'then position(lower(v_q)in lower(s.to_branch_code))>0 when 'to_branch_name'then position(lower(v_q)in lower(s.to_branch_name))>0 when 'creator_name'then position(lower(v_q)in lower(coalesce(s.created_by_name,'')))>0 when 'note'then position(lower(v_q)in lower(coalesce(s.note,'')))>0 when 'product_code'then exists(select 1 from public.internal_sale_items i where i.internal_sale_id=s.id and position(lower(v_q)in lower(coalesce(i.product_code,'')))>0)when 'product_name'then exists(select 1 from public.internal_sale_items i where i.internal_sale_id=s.id and position(lower(v_q)in lower(coalesce(i.product_name,'')))>0)else position(lower(v_q)in lower(s.code))>0 or position(lower(v_q)in lower(s.from_branch_name))>0 or position(lower(v_q)in lower(s.to_branch_name))>0 or position(lower(v_q)in lower(coalesce(s.created_by_name,'')))>0 or position(lower(v_q)in lower(coalesce(s.note,'')))>0 or exists(select 1 from public.internal_sale_items i where i.internal_sale_id=s.id and(position(lower(v_q)in lower(coalesce(i.product_code,'')))>0 or position(lower(v_q)in lower(coalesce(i.product_name,'')))>0))end)and(coalesce(array_length(p_statuses,1),0)=0 or s.status=any(p_statuses))and(p_date_from is null or s.created_at>=p_date_from)and(p_date_to_exclusive is null or s.created_at<p_date_to_exclusive)and(p_from_branch_id is null or s.from_branch_id=p_from_branch_id)and(p_to_branch_id is null or s.to_branch_id=p_to_branch_id)and(p_created_by is null or s.created_by=p_created_by)and(p_amount_min is null or s.total>=p_amount_min)and(p_amount_max is null or s.total<=p_amount_max)),ranked as(select f.*,row_number()over(order by f.created_at desc,f.id)rn from filtered f),page_rows as(select * from ranked where rn>v_page*v_size and rn<=(v_page+1)*v_size order by rn),summary as(select count(*)::bigint total_count,count(*)filter(where status='completed')::bigint completed_count,count(*)filter(where status='cancelled')::bigint cancelled_count,coalesce(sum(total),0)::numeric total_value,coalesce(sum(total)filter(where status='completed'),0)::numeric completed_value,coalesce(sum(tax_amount),0)::numeric tax_value from filtered)
  select jsonb_build_object('items',coalesce((select jsonb_agg((to_jsonb(r)-'rn'-'from_branch_code'-'from_branch_name'-'to_branch_code'-'to_branch_name'-'created_by_name')||jsonb_build_object('from_branch',jsonb_build_object('code',r.from_branch_code,'name',r.from_branch_name),'to_branch',jsonb_build_object('code',r.to_branch_code,'name',r.to_branch_name),'creator',case when r.created_by_name is null then null else jsonb_build_object('full_name',r.created_by_name)end)order by r.rn)from page_rows r),'[]'::jsonb),'total',(select total_count from summary),'summary',(select jsonb_build_object('completedCount',completed_count,'cancelledCount',cancelled_count,'totalValue',total_value,'completedValue',completed_value,'taxValue',tax_value)from summary))into v_result;return v_result;
end $$;

